// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _test(uint256 x) internal {
        x = bound(x, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(x > 0);
        vm.assume(address(this).balance >= x);
        try c.addToBalance{value: x}() {} catch { return; }
        assertTrue(c.getBalance(address(this)) == x);
    }

    function testFuzz_test(uint256 x) public {
        _test(x);
    }

    receive() external payable {}

    fallback() external payable {}
}
